def min_cost(n, cuts):
    pos = [0] + sorted(cuts) + [n]

    def cost(i, j):            # make every cut strictly inside pos[i]..pos[j]
        if j - i < 2:
            return 0
        return pos[j] - pos[i] + min(cost(i, k) + cost(k, j)
                                     for k in range(i + 1, j))
    return cost(0, len(pos) - 1)

