def min_cost(n, cuts):
    pos = [0] + sorted(cuts) + [n]
    m = len(pos)
    dp = [[0] * m for _ in range(m)]
    for gap in range(2, m):
        for i in range(m - gap):
            j = i + gap
            dp[i][j] = pos[j] - pos[i] + min(dp[i][k] + dp[k][j]
                                             for k in range(i + 1, j))
    return dp[0][m - 1]
